bool bitmap_full(bitmap_t *bitmap, const bitmap_info_t *binfo) {
    for (unsigned i = 0; i < binfo->ngroups - 1; i++) {
        if (bitmap[i] != ~(bitmap_t)0) {
            return false;
        }
    }
    // Handle the last group if it's partial
    if (binfo->ngroups > 0) {
        unsigned last_group_bits = binfo->nbits % (sizeof(bitmap_t) * 8);
        if (last_group_bits == 0) {
            last_group_bits = sizeof(bitmap_t) * 8;
        }
        bitmap_t mask = (last_group_bits == sizeof(bitmap_t) * 8)
            ? ~(bitmap_t)0
            : ((bitmap_t)1 << last_group_bits) - 1;
        if (bitmap[binfo->ngroups - 1] != mask) {
            return false;
        }
    }
    return true;
}

